void mainImage(out vec4 c, in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;
 vec2 target=vec2(U.p0.x,1.0-U.p1.x);
 vec2 d=(uv-target)*vec2(iResolution.x/iResolution.y,1.0);
 float ring=(1.0-smoothstep(0.005,0.015,abs(length(d)-0.09)))*clamp(U.p2.x,0.0,1.0);
 c=vec4(mix(texture(iChannel0,uv).rgb,vec3(0.1,1.0,0.9),ring),1.0);
}
